import{_ as t,o,c as a,ag as n}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 16 — Final Presentations","description":"","frontmatter":{"source":"weeks/16-final-presentations/README.md"},"headers":[],"relativePath":"weeks/16-final-presentations/index.md","filePath":"weeks/16-final-presentations/index.md"}'),r={name:"weeks/16-final-presentations/index.md"};function s(i,e,h,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="week-16--final-presentations" tabindex="-1">Week 16 — Final Presentations <a class="header-anchor" href="#week-16--final-presentations" aria-label="Permalink to &quot;Week 16 — Final Presentations&quot;">​</a></h1><blockquote><p>You show your capstone working, explain how you built it, and hand in a version you can stand behind.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><p>Week 16 is finals week. There is no final examination, and there are no regular studios, no lab and no homework: just the final presentations and the capstone deadline.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>The course&#39;s scheduled final exam period (University Regulation H-1-b): [day, time and room, posted on Canvas]</td></tr><tr><td><strong>Due at the start of the period</strong></td><td>Your capstone on Canvas (<a href="#final-submission">checklist</a>), and your final reflection with your revised AI-use rules (<a href="./../15-ship-it/homework.html#5-final-reflection-and-revised-ai-use-rules-about-15-h">week 15 homework</a>)</td></tr><tr><td><strong>In the period</strong></td><td>Each student or pair gives a <strong>five-minute presentation with a live demo</strong>, then answers a question or two from the class and the instructor, at least one about their code (🔴 AI off)</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: last fixes before the deadline, in the Safe Loop · 🔴 AI off: answering questions after your presentation</td></tr><tr><td><strong>Graded as</strong></td><td>Part of the <a href="./../../assessment/rubrics.html#capstone">capstone rubric</a>: the presentation in the &quot;README and final presentation&quot; row, and your answers about your code in the &quot;Code you can explain&quot; row</td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../projects/capstone.html#what-done-means">What &quot;done&quot; means</a> · <a href="./../15-ship-it/polish-checklist.html">Polish checklist</a> · <a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a></td></tr><tr><td><strong>Time</strong></td><td>Before the period about 1 h · the presentations up to 2 h</td></tr></tbody></table><p>Canvas is the course&#39;s learning management system. Your submission links and your final reflection go there; the reflection never goes in a repo.</p><h2 id="before-the-presentations" tabindex="-1">Before the presentations <a class="header-anchor" href="#before-the-presentations" aria-label="Permalink to &quot;Before the presentations&quot;">​</a></h2><ul><li>☐ Open your <strong>production URL</strong> in a private window, on a phone and a laptop, and check the main user story works.</li><li>☐ Open your Supabase project, if you have one, <strong>the day before</strong>, and restore it if it&#39;s paused (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>).</li><li>☐ <strong>Submit the capstone on Canvas</strong> before the period starts (<a href="#final-submission">checklist below</a>).</li><li>☐ Practice your presentation once, out loud and timed.</li><li>☐ Optional: keep a short screen recording or a few screenshots of the main story as a backup, in case the live demo fails. Use made-up data only.</li></ul><h2 id="your-five-minute-presentation" tabindex="-1">Your five-minute presentation <a class="header-anchor" href="#your-five-minute-presentation" aria-label="Permalink to &quot;Your five-minute presentation&quot;">​</a></h2><ol><li><strong>Problem</strong> (about 30 seconds): who the app is for and what it solves.</li><li><strong>Live demo</strong> (2–3 minutes): the main user story at the production URL, your feature types, and one edge case handled well.</li><li><strong>How it works</strong> (about 30 seconds): how it&#39;s built, where the data and keys live, and where authorization is enforced.</li><li><strong>What broke and what you learned</strong> (about 30 seconds): one honest moment, and one item from your Known issues section.</li></ol><p>Then the class and your instructor ask a question or two, and at least one of them is about your code: what a function does, why you wrote it that way, or where authorization is enforced. Answer with the AI off. You still have your own code, so you can open it and point to the line. Your answers feed the capstone&#39;s &quot;Code you can explain&quot; row. If you can&#39;t yet explain a core part, your instructor may follow up with a short <a href="./../../assessment/#academic-integrity">&quot;explain it or redo it&quot;</a> conversation, which can lift that row.</p><p>Pairs share the five minutes, and both partners speak. Each partner answers questions about the code, mostly about the parts the contribution statement says they built.</p><p><strong>If the live demo fails,</strong> show your backup recording or screenshots and keep going. Then fix it, or name it in Known issues. The rubric doesn&#39;t grade the vendor.</p><p><strong>Can&#39;t be there?</strong> If you miss the presentations for a reason the University recognizes (Regulations M-1 and M-3), tell your instructor as early as you can; they&#39;ll arrange a make-up before the grade deadline (<a href="./../../assessment/#absences-and-make-up-work">Absences and make-up work</a>).</p><h2 id="final-submission" tabindex="-1">Final submission <a class="header-anchor" href="#final-submission" aria-label="Permalink to &quot;Final submission&quot;">​</a></h2><p>Your capstone is done when every box is ticked. Everything is due at the start of the final exam period.</p><ul><li>☐ Everything in <a href="./../../projects/capstone.html#what-done-means">What &quot;done&quot; means</a> is true, including the <a href="./../15-ship-it/homework.html">week 15 deliverables</a>.</li><li>☐ <strong>On Canvas:</strong> the repo URL, the <strong>production URL with a screenshot</strong> of the app working there, and the link to your final commit. Pairs: the signed contribution statement.</li><li>☐ <strong>On Canvas:</strong> your final reflection with your revised personal AI-use rules (🔴 AI off), from the week 15 homework.</li><li>☐ <strong>Your presentation</strong>, given in the final exam period, or the make-up your instructor arranged.</li></ul><h3 id="the-final-milestone" tabindex="-1">The final milestone <a class="header-anchor" href="#the-final-milestone" aria-label="Permalink to &quot;The final milestone&quot;">​</a></h3><p>The row below is copied word for word from the <a href="./../../projects/capstone.html#milestones">capstone milestones</a>:</p><table tabindex="0"><thead><tr><th>Milestone</th><th>Due</th><th>Deliverables</th><th>Graded as</th></tr></thead><tbody><tr><td><strong>Final</strong> (finals week)</td><td>At the start of the course&#39;s scheduled final exam period, on Canvas, before the University&#39;s grade deadline</td><td>• Everything in <a href="./../../projects/capstone.html#what-done-means">What done means</a><br>• On Canvas: the <strong>production URL and a screenshot</strong> of it working, the repo URL and the link to your final commit<br>• A <strong>five-minute presentation</strong> with a live demo, in the final exam period<br>• Your <a href="./../../projects/capstone.html#final-reflection">final reflection</a> on Canvas (🔴 AI off), with your revised personal AI-use rules (week 15 homework)</td><td><a href="./../../assessment/rubrics.html#capstone">Capstone rubric</a>; the final reflection in <a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">Assignments</a></td></tr></tbody></table><p>We grade the commit you submitted, as it was at the deadline.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Supabase free projects pause when nobody uses them (<a href="./../../TOOLS.html">Tool Handout</a>). Restore yours before you submit and check the production URL still works.</p></div><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><p><strong>Keep going: a roadmap after the course.</strong> You now have the loop and the trust boundary. Tools will change; those won&#39;t. Where to go next, roughly in order:</p><ol><li><strong>Ship one more thing you&#39;ll use.</strong> The fastest way to keep the skill is to build something small and real, start to finish, on your own.</li><li><strong>Deepen the fundamentals</strong> you practiced with the AI off: reading errors, explaining functions, writing tests, git branches and reverts. These are what let you go faster with AI, not slower (<a href="./../../research/landscape-report-2026-09.html">September report</a>).</li><li><strong>Learn the next rung when you need it</strong>, not before. A background or cloud agent, MCP servers, GitHub Actions, a framework: pick these up on a project that needs them.</li><li><strong>Keep up without chasing every tool.</strong> Follow a few signal sources; when a free tier changes, switch to a fallback (you&#39;ve practiced this). The open standards, <strong>AGENTS.md, MCP and git</strong>, are the safe bet.</li><li><strong>Stay safe by habit:</strong> privacy settings on new tools, secrets on the server, grants and RLS together on every table, read the diff, approvals on, check packages. The week 14 security checklist works on any project.</li><li><strong>Keep a portfolio.</strong> Leave your repos public with good READMEs, if you&#39;re comfortable. That&#39;s your proof that you can direct AI to build real, explainable software.</li></ol><p>More: <a href="./../../resources/reading-list.html">Reading List</a>.</p><p>Congratulations: you built, secured, shipped and can explain real software. That&#39;s the whole course.</p>',27)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
